fn numpy_insert<T>(arr: Vec<T>, idx: usize, value: T) -> Vec<T> {
    let n = arr.len();
    // Pre-allocate a new Vec with space for one more element
    let mut result = Vec::with_capacity(n + 1);

    // Iterate through the original array, inserting `value` when we reach `idx`.
    for (i, elem) in arr.into_iter().enumerate() {
        if i == idx {
            result.push(value);
        }
        result.push(elem);
    }

    // If idx == n, we never hit i == idx in the loop, so append at the end.
    if idx == n {
        result.push(value);
    }

    result
}

